use axum::{
    extract::{Query, State},
    http::StatusCode,
};
use serde::{Deserialize, Serialize};

use crate::{
    domain::{
        models::entity_search::{Entity, EntitySearchError, EntitySearchRequest},
        services::entity_search::EntitySearchService,
    },
    inbound::http::{error::ApiError, state::AppState, success::ApiSuccess},
};

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct SearchEntitiesHttpRequest {
    term: String,
    max_entries: u8,
    strictness: Option<f32>,
}

impl SearchEntitiesHttpRequest {
    /// Converts the HTTP request body into a domain request.
    fn try_into_domain(self) -> Result<EntitySearchRequest, EntitySearchError> {
        match self.strictness {
            Some(s) => EntitySearchRequest::new_with_strictness(self.term, self.max_entries, s),
            None => EntitySearchRequest::new_strict(self.term, self.max_entries),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntityResponseData {
    entities: Vec<SearchEntity>,
}

impl From<&[Entity]> for SearchEntityResponseData {
    fn from(value: &[Entity]) -> Self {
        let entities = value.iter().map(SearchEntity::from).collect();
        Self { entities }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntity {
    name: String,
    kind: String,
    funder_kind: Option<String>,
}

impl From<&Entity> for SearchEntity {
    fn from(value: &Entity) -> Self {
        Self {
            name: value.name().to_string(),
            kind: value.kind().to_string(),
            funder_kind: value.funder_kind().map(String::from),
        }
    }
}

impl From<EntitySearchError> for ApiError {
    fn from(value: EntitySearchError) -> Self {
        match value {
            EntitySearchError::InvalidTerm(_)
            | EntitySearchError::InvalidStrictness(_)
            | EntitySearchError::TooFewEntries => Self::UnprocessibleEntity(value.to_string()),
            EntitySearchError::UnexpectedError(_) => Self::InternalServerError,
        }
    }
}

pub async fn search_entities<E: EntitySearchService>(
    State(state): State<AppState<E>>,
    Query(query): Query<SearchEntitiesHttpRequest>,
) -> Result<ApiSuccess<SearchEntityResponseData>, ApiError> {
    let domain_req = query.try_into_domain()?;
    state
        .entity_search_service
        .search_entities(&domain_req)
        .await
        .map_err(ApiError::from)
        .map(|ref entities| ApiSuccess::new(StatusCode::OK, entities.as_slice().into()))
}
use std::sync::Arc;

use tokio::net::TcpListener;

use crate::{
    domain::services::entity_search::Service as EntitySearchService,
    inbound::http::{config::ServerConfig, routes::routes, state::AppState},
    outbound::ExposedDatabase,
};

/// Loads server configuration and serves HTTP on port 6999 or an available port.
///
/// # Errors
/// Returns an error if configuration, runtime creation, or server startup fails.
pub fn run_server() -> anyhow::Result<()> {
    dotenvy::dotenv().ok();
    let config = ServerConfig::from_env()?;

    tokio::runtime::Runtime::new()?.block_on(async {
        let listener = match TcpListener::bind("0.0.0.0:6999").await {
            Err(error) if error.kind() == std::io::ErrorKind::AddrInUse => {
                TcpListener::bind("0.0.0.0:0").await?
            }
            result => result?,
        };
        println!(
            "Listening on http://localhost:{}",
            listener.local_addr()?.port()
        );
        serve_exposed(&config, listener).await
    })
}

/// Starts an `exposed` HTTP server
///
/// # Errors
/// - When the HTTP server fails
pub async fn serve_exposed(config: &ServerConfig, listener: TcpListener) -> anyhow::Result<()> {
    let db = ExposedDatabase::new(&config.connection_string).await;
    let service = EntitySearchService::new(db.clone(), db);

    let state = AppState {
        entity_search_service: Arc::new(service),
    };
    let router = routes().with_state(state);

    axum::serve(listener, router).await?;

    Ok(())
}
//! CLI inbound port

use std::{path::PathBuf, str::FromStr};

use clap::{Parser, Subcommand};

use crate::{
    domain::{
        models::entity_ingestion::{
            DeclarationIngestionStage, EntityIngestionRequest, IngestionKey, MemberIngestionStage,
        },
        services::declaration_fetch::DeclarationFetcherService,
        services::entity_ingestion::{
            EntityFetcherService, EntityIngesterService, FetcherService, IngesterService,
        },
    },
    inbound::cli::config::{DataConfig, DeclarationFetcherConfig, FetcherConfig, LoaderConfig},
    outbound::{ExposedDataPipeline, ExposedDatabase, ParliamentApiClient},
};

pub mod config;

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    /// Show the latest ingestion key and directory path.
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        config: PathBuf,
    },
    Declarations {
        stage: String,
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    Members {
        stage: String,
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// # Errors
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
    match args.command {
        DataCommands::Latest { config } => {
            let config = LoaderConfig::try_from(&config)?;
            match ExposedDataPipeline::latest_ingestion(&config.data_dir).await? {
                Some((path, key)) => {
                    println!("Ingestion key: {key}");
                    println!("Path: {}", path.display());
                }
                None => println!("No ingestion runs found."),
            }
        }
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => {
            let DeclarationIngestionStage::Fetch = DeclarationIngestionStage::from_str(&stage)?;
            let config = DeclarationFetcherConfig::try_from(&config)?;
            let data_config = DataConfig::from_env()?;
            let api = ParliamentApiClient::new(config.batch_size)?;
            let db = ExposedDatabase::new(&data_config.connection_string).await;
            let fs = ExposedDataPipeline::new_with_ingestion_key(
                &config.data_dir,
                ingestion_key.unwrap_or_default(),
            )?;
            let service = DeclarationFetcherService::new(db, api, fs);
            service.fetch_declarations().await?;
        }
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => {
            let stage = MemberIngestionStage::from_str(&stage)?;
            let ingestion_key = ingestion_key.unwrap_or_default();
            match stage {
                MemberIngestionStage::Fetch => {
                    let config = FetcherConfig::try_from(&config)?;
                    let api = ParliamentApiClient::new(config.batch_size)?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let service = FetcherService::new(fs, api);

                    let req = EntityIngestionRequest {};
                    service.fetch_members(&req).await?;
                }
                MemberIngestionStage::Load => {
                    let config = LoaderConfig::try_from(&config)?;
                    let data_config = DataConfig::from_env()?;
                    let fs = ExposedDataPipeline::new_with_ingestion_key(
                        &config.data_dir,
                        ingestion_key,
                    )?;
                    let db = ExposedDatabase::new(&data_config.connection_string).await;
                    let service = IngesterService::new(fs, db);

                    service.load_members().await?;
                }
            }
        }
    }
    Ok(())
}
